const REPO_URL = "https://github.com/JavidPanel/JavidPanel";
const DEFAULT_REPO = "JavidPanel/JavidPanel";
const OFFICIAL_BOT_URL = "https://t.me/javidpanelbot";
const OFFICIAL_CHANNEL_URL = "https://t.me/javidpnl";
const CF_API = "https://api.cloudflare.com/client/v4";
const CLOUDFLARE_SIGNUP_URL = "https://dash.cloudflare.com/sign-up";
const TOKEN_TEMPLATE_URL = "https://dash.cloudflare.com/profile/api-tokens?permissionGroupKeys=%5B%7B%22key%22%3A%22workers_scripts%22%2C%22type%22%3A%22edit%22%7D%2C%7B%22key%22%3A%22workers_kv_storage%22%2C%22type%22%3A%22edit%22%7D%2C%7B%22key%22%3A%22account_settings%22%2C%22type%22%3A%22read%22%7D%5D&accountId=%2A&zoneId=all&name=JavidPanel%20Installer";
const enc = new TextEncoder();
const dec = new TextDecoder();

class AppError extends Error { constructor(message,status=400){super(message);this.status=status;} }
function json(data,status=200,headers={}){return new Response(JSON.stringify(data),{status,headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store","x-content-type-options":"nosniff",...headers}})}
function html(body,status=200,headers={}){return new Response(body,{status,headers:{"content-type":"text/html; charset=utf-8","cache-control":"no-store","x-frame-options":"DENY","content-security-policy":"default-src 'self'; img-src 'self' data: https:; style-src 'unsafe-inline' 'self'; script-src 'unsafe-inline' 'self'; connect-src 'self'; frame-ancestors 'none'","referrer-policy":"no-referrer",...headers}})}
function text(body,status=200){return new Response(body,{status,headers:{"content-type":"text/plain; charset=utf-8","cache-control":"no-store"}})}
function nowIso(){return new Date().toISOString()}
function randHex(n){const a=new Uint8Array(n);crypto.getRandomValues(a);return Array.from(a,x=>x.toString(16).padStart(2,"0")).join("")}
function uuid(){return crypto.randomUUID?crypto.randomUUID():`${randHex(4)}-${randHex(2)}-4${randHex(2).slice(1)}-a${randHex(2).slice(1)}-${randHex(6)}`}
function randomPath(){return "jp-"+randHex(9)}
function safeName(s){return String(s||"").toLowerCase().replace(/[^a-z0-9-]/g,"-").replace(/-+/g,"-").replace(/^-|-$/g,"").slice(0,50)||"javid-panel"}
function clampInt(v,min,max,dflt){const n=parseInt(v,10);return Number.isFinite(n)?Math.max(min,Math.min(max,n)):dflt}
function b64u(bytes){return btoa(String.fromCharCode(...new Uint8Array(bytes))).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/g,"")}
function unb64u(s){const v=String(s||"").replace(/-/g,"+").replace(/_/g,"/");return Uint8Array.from(atob(v+"===".slice((v.length+3)%4)),c=>c.charCodeAt(0))}
async function sha256Bytes(v){return new Uint8Array(await crypto.subtle.digest("SHA-256",typeof v==="string"?enc.encode(v):v))}
async function sha256Hex(v){return Array.from(await sha256Bytes(v),x=>x.toString(16).padStart(2,"0")).join("")}
function strongPassword(){const a="ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@$&*_.+-";const r=crypto.getRandomValues(new Uint8Array(26));return Array.from(r,x=>a[x%a.length]).join("")}
function timingSafeEq(a,b){a=String(a||"");b=String(b||"");if(a.length!==b.length)return false;let x=0;for(let i=0;i<a.length;i++)x|=a.charCodeAt(i)^b.charCodeAt(i);return x===0}

async function kvJson(env,key,fallback){try{const x=await env.BOT_KV.get(key,{type:"json"});return x??fallback}catch{return fallback}}
async function setJson(env,key,val,opts){await env.BOT_KV.put(key,JSON.stringify(val),opts)}
async function indexAdd(env,key,id){const a=await kvJson(env,key,[]);if(!a.includes(id)){a.unshift(id);await setJson(env,key,a)}return a}
async function indexRemove(env,key,id){const a=(await kvJson(env,key,[])).filter(x=>x!==id);await setJson(env,key,a);return a}
async function getConfig(env){const stored=await kvJson(env,"config",{});const defaults={maxPanelsPerUser:2,botEnabled:true,broadcastBatch:25,supportText:"پشتیبانی پنل جاوید",welcomeText:"سلام 👋 خوش اومدی. این ربات نصب و نگهداری پنل جاوید رو قدم‌به‌قدم و ساده انجام می‌ده.",buttonInstall:"🚀 نصب پنل جدید",buttonPanels:"🧩 پنل‌های من",buttonDocs:"📚 راهنمای کامل",buttonAbout:"ℹ️ درباره پنل جاوید",githubRepo:DEFAULT_REPO,githubBranch:"main",forcedJoinEnabled:false,forcedJoinChats:[{chatId:"@javidpnl",title:"کانال رسمی پنل جاوید",url:OFFICIAL_CHANNEL_URL}]};const c=Object.assign(defaults,stored);if(c.supportText==="پشتیبانی JavidPanel")c.supportText="پشتیبانی پنل جاوید";if(c.welcomeText==="سلام 👋 خوش اومدی! اینجا نصب و نگهداری JavidPanel تا حد ممکن خودکار و ساده انجام می‌شه.")c.welcomeText="سلام 👋 خوش اومدی! اینجا نصب و نگهداری پنل جاوید تا حد ممکن خودکار و ساده انجام می‌شه.";if(c.buttonAbout==="ℹ️ درباره JavidPanel")c.buttonAbout="ℹ️ درباره پنل جاوید";if(Array.isArray(c.forcedJoinChats))c.forcedJoinChats=c.forcedJoinChats.map(x=>x&&x.title==="کانال رسمی JavidPanel"?{...x,title:"کانال رسمی پنل جاوید"}:x);return c}

function requireMaster(env){if(!env.MASTER_KEY||String(env.MASTER_KEY).length<32)throw new AppError("MASTER_KEY تنظیم نشده است. اسکریپت نصب/تعمیر Installer را اجرا کنید.",503)}
async function aesKey(env){requireMaster(env);return crypto.subtle.importKey("raw",await sha256Bytes(String(env.MASTER_KEY)),{name:"AES-GCM"},false,["encrypt","decrypt"])}
async function seal(env,value){const iv=crypto.getRandomValues(new Uint8Array(12));const ct=await crypto.subtle.encrypt({name:"AES-GCM",iv},await aesKey(env),enc.encode(String(value)));return b64u(iv)+"."+b64u(ct)}
async function openSeal(env,value){const [a,b]=String(value||"").split(".");if(!a||!b)throw new AppError("Encrypted value is invalid",500);return dec.decode(await crypto.subtle.decrypt({name:"AES-GCM",iv:unb64u(a)},await aesKey(env),unb64u(b)))}
async function setSecret(env,name,value){const key="secret:"+name;if(value==null||String(value)===""){await env.BOT_KV.delete(key);return}await env.BOT_KV.put(key,await seal(env,String(value)))}
async function getSecret(env,name){const v=await env.BOT_KV.get("secret:"+name);if(!v)return "";try{return await openSeal(env,v)}catch{return ""}}
async function secretState(env){const names=["BOT_TOKEN","TELEGRAM_WEBHOOK_SECRET","GITHUB_TOKEN"];const out={};for(const n of names)out[n]=!!(await env.BOT_KV.get("secret:"+n));return out}

const ADMIN_PBKDF2_ITERATIONS = 100000;
async function derivePassword(password,salt,iterations=ADMIN_PBKDF2_ITERATIONS){iterations=clampInt(iterations,1,100000,ADMIN_PBKDF2_ITERATIONS);const key=await crypto.subtle.importKey("raw",enc.encode(String(password)),"PBKDF2",false,["deriveBits"]);const bits=await crypto.subtle.deriveBits({name:"PBKDF2",hash:"SHA-256",salt:unb64u(salt),iterations},key,256);return b64u(bits)}
async function adminConfigured(env){return !!(await env.BOT_KV.get("admin:auth"))}
async function setupAdmin(env,password){requireMaster(env);password=String(password||"");if(password.length<12)throw new AppError("رمز مدیریت باید حداقل ۱۲ کاراکتر باشد.",400);if(await adminConfigured(env))throw new AppError("راه‌اندازی قبلاً انجام شده است.",409);const salt=b64u(crypto.getRandomValues(new Uint8Array(16)));const iterations=ADMIN_PBKDF2_ITERATIONS;const hash=await derivePassword(password,salt,iterations);await setJson(env,"admin:auth",{salt,hash,iterations,algorithm:"PBKDF2-SHA256",createdAt:nowIso()});return true}
async function verifyAdmin(env,password){const a=await kvJson(env,"admin:auth",null);if(!a)return false;const h=await derivePassword(password,a.salt,a.iterations||ADMIN_PBKDF2_ITERATIONS);return timingSafeEq(h,a.hash)}
async function hmac(env,s){requireMaster(env);const k=await crypto.subtle.importKey("raw",await sha256Bytes("session:"+String(env.MASTER_KEY)),{name:"HMAC",hash:"SHA-256"},false,["sign"]);return b64u(await crypto.subtle.sign("HMAC",k,enc.encode(s)))}
async function adminCookie(env){const exp=Math.floor(Date.now()/1000)+43200;const body=`admin.${exp}`;return body+"."+await hmac(env,body)}
async function isAdmin(req,env){try{const m=(req.headers.get("cookie")||"").match(/(?:^|;\s*)jp_admin=([^;]+)/);if(!m)return false;const p=m[1].split(".");if(p.length!==3||p[0]!=="admin"||Number(p[1])<Date.now()/1000)return false;const body=`${p[0]}.${p[1]}`;return timingSafeEq(p[2],await hmac(env,body))}catch{return false}}

async function tg(env,method,payload){const token=await getSecret(env,"BOT_TOKEN");if(!token)throw new AppError("توکن ربات تلگرام هنوز تنظیم نشده است.",400);const r=await fetch(`https://api.telegram.org/bot${token}/${method}`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(payload)});const d=await r.json().catch(()=>({ok:false,description:`HTTP ${r.status}`}));if(!d.ok)throw new AppError(d.description||"ارتباط با تلگرام ناموفق بود.",502);return d.result}
function withHome(reply_markup){const home={text:"🏠 بازگشت به خانه",callback_data:"menu"};const m=reply_markup&&Array.isArray(reply_markup.inline_keyboard)?{...reply_markup,inline_keyboard:reply_markup.inline_keyboard.map(r=>Array.isArray(r)?r.slice():r)}:{inline_keyboard:[]};const exists=m.inline_keyboard.some(r=>Array.isArray(r)&&r.some(b=>b&&b.callback_data==="menu"));if(!exists)m.inline_keyboard.push([home]);return m}
async function sendText(env,chat_id,message,reply_markup){return tg(env,"sendMessage",{chat_id,text:message,parse_mode:"HTML",disable_web_page_preview:true,reply_markup:withHome(reply_markup)})}
async function sendPhoto(env,chat_id,photo,caption,reply_markup){return tg(env,"sendPhoto",{chat_id,photo,caption,parse_mode:"HTML",reply_markup:withHome(reply_markup)})}
async function answerCb(env,id,textMsg=""){try{return await tg(env,"answerCallbackQuery",{callback_query_id:id,text:textMsg,show_alert:false})}catch{}}
function normalizeForcedChats(v){if(!Array.isArray(v))return [];const out=[];for(const x of v.slice(0,12)){if(!x)continue;const chatId=String(x.chatId||"").trim();if(!chatId)continue;const title=String(x.title||chatId).trim().slice(0,80)||chatId;let url=String(x.url||"").trim();if(!url&&chatId.startsWith("@"))url="https://t.me/"+chatId.slice(1);if(url&&!/^https:\/\/t\.me\//i.test(url))url="";out.push({chatId,title,url})}return out}
async function membershipStatus(env,userId){const cfg=await getConfig(env);const chats=normalizeForcedChats(cfg.forcedJoinChats);if(!cfg.forcedJoinEnabled||!chats.length)return {required:false,ok:true,missing:[],errors:[]};const missing=[],errors=[];for(const c of chats){try{const m=await tg(env,"getChatMember",{chat_id:c.chatId,user_id:Number(userId)});const st=String(m?.status||"");const joined=st==="creator"||st==="administrator"||st==="member"||(st==="restricted"&&m?.is_member===true);if(!joined)missing.push(c)}catch(e){errors.push({chat:c,error:String(e.message||e)});missing.push(c)}}return {required:true,ok:missing.length===0,missing,errors}}
async function membershipPrompt(env,chatId,userId){const st=await membershipStatus(env,userId);if(st.ok)return true;const rows=st.missing.map(c=>c.url?[{text:"عضویت در «"+c.title+"»",url:c.url}]:[{text:"عضویت در «"+c.title+"»",callback_data:"noop"}]);rows.push([{text:"✅ عضو شدم؛ دوباره بررسی کن",callback_data:"checkjoin"}]);await sendText(env,chatId,"<b>برای ادامه، عضویت لازم است</b> 🔐\n\nلطفاً ابتدا عضو کانال‌ها یا گروه‌های زیر شو. بعد روی دکمه «عضو شدم؛ دوباره بررسی کن» بزن.\n\nربات فقط وضعیت عضویت را بررسی می‌کند و به پیام‌ها یا اطلاعات خصوصی تو دسترسی ندارد.",{inline_keyboard:rows});return false}
async function mainKeyboard(env){const c=await getConfig(env);return {inline_keyboard:[[{text:c.buttonInstall,callback_data:"install"},{text:c.buttonPanels,callback_data:"mypanels"}],[{text:c.buttonDocs,callback_data:"docs"},{text:c.buttonAbout,callback_data:"about"}],[{text:"🆕 ساخت حساب کلادفلیر",url:CLOUDFLARE_SIGNUP_URL}],[{text:"🔐 ساخت توکن دسترسی کلادفلیر",url:TOKEN_TEMPLATE_URL}],[{text:"📣 کانال رسمی",url:OFFICIAL_CHANNEL_URL},{text:"🌐 گیت‌هاب",url:REPO_URL}]]}}
function friendlyUserError(e){const m=String(e&&e.message||e||"");if(/حداکثر تعداد نصب/.test(m))return m;if(/نسخه عمومی/.test(m))return "هنوز نسخه عمومی آماده نصب نیست. کمی بعد دوباره تلاش کن.";if(/free usage limit|daily.*limit|write quota|kv.*quota|reached.*limit/i.test(m))return "سقف روزانه نوشتن Cloudflare Workers KV در حساب مقصد تمام شده است. در پلن Free حداکثر ۱۰۰۰ Write در روز مجاز است و سهمیه ساعت 00:00 UTC ریست می‌شود. حجم Storage معیار این محدودیت نیست؛ بعد از ریست روزانه، ارتقای Workers Paid یا استفاده از حساب دیگری دوباره تلاش کن.";if(/token|authorization|permission|account|cloudflare|http|forbidden|unauthorized/i.test(m))return "توکن دسترسی کلادفلیر معتبر نیست یا مجوزهای لازم کامل نیست. از لینک داخل ربات یک توکن تازه بساز و دوباره بفرست.";return "عملیات کامل نشد. یک بار دیگر از خانه ربات شروع کن. اگر مشکل تکرار شد، کانال رسمی پنل جاوید را بررسی کن."}

async function touchUser(env,from){const id=String(from.id);let u=await kvJson(env,"user:"+id,null);const n=nowIso();if(!u){u={id,firstName:from.first_name||"",lastName:from.last_name||"",username:from.username||"",createdAt:n,lastSeenAt:n,blocked:false,installCount:0};await indexAdd(env,"users:index",id)}else{u.firstName=from.first_name||u.firstName;u.lastName=from.last_name||u.lastName;u.username=from.username||u.username;u.lastSeenAt=n}await setJson(env,"user:"+id,u);return u}
async function userPanels(env,userId){const ids=await kvJson(env,"userpanels:"+userId,[]);const out=[];for(const id of ids){const p=await kvJson(env,"panel:"+id,null);if(p)out.push(p)}return out}

async function cf(token,path,init={}){const headers=new Headers(init.headers||{});headers.set("Authorization","Bearer "+token);if(init.body&&typeof init.body==="string"&&!headers.has("content-type"))headers.set("content-type","application/json");const r=await fetch(CF_API+path,{...init,headers});const body=await r.text();let d={};try{d=JSON.parse(body)}catch{d={success:false,errors:[{message:body.slice(0,500)}]}}if(!r.ok||d.success===false){const msg=(d.errors||[]).map(x=>x.message).join("; ")||`Cloudflare HTTP ${r.status}`;if(r.status===429&&/free usage limit|daily.*limit|write quota|kv.*quota|reached.*limit/i.test(msg))throw new AppError("سقف روزانه نوشتن Cloudflare Workers KV در حساب مقصد تمام شده است. پلن Free فقط 1000 Write در روز دارد و سهمیه ساعت 00:00 UTC ریست می‌شود. این محدودیت به حجم Storage ارتباطی ندارد.",429);throw new AppError(msg,502)}return d.result}
async function verifyCfToken(token){return cf(token,"/user/tokens/verify")}
async function cfAccounts(token){return cf(token,"/accounts?per_page=50")}
async function cfSubdomain(token,accountId){return cf(token,`/accounts/${accountId}/workers/subdomain`)}
async function createKv(token,accountId,title){return cf(token,`/accounts/${accountId}/storage/kv/namespaces`,{method:"POST",body:JSON.stringify({title})})}
async function deleteKv(token,accountId,id){try{await cf(token,`/accounts/${accountId}/storage/kv/namespaces/${id}`,{method:"DELETE"});return true}catch(e){return false}}
async function kvPut(token,accountId,namespaceId,key,value){const r=await fetch(`${CF_API}/accounts/${accountId}/storage/kv/namespaces/${namespaceId}/values/${encodeURIComponent(key)}`,{method:"PUT",headers:{Authorization:`Bearer ${token}`,"content-type":"text/plain;charset=utf-8"},body:String(value)});const body=await r.text();let d={};try{d=JSON.parse(body)}catch{}if(!r.ok||d.success===false){const msg=(d.errors||[]).map(x=>x.message).join("; ")||`KV write HTTP ${r.status}`;if(r.status===429&&/free usage limit|daily.*limit|write quota|kv.*quota|reached.*limit/i.test(msg))throw new AppError(`Cloudflare KV write ${key}: سقف روزانه Workers KV در حساب مقصد تمام شده است. پلن Free فقط 1000 Write در روز دارد؛ سهمیه در 00:00 UTC ریست می‌شود و حجم Storage معیار این محدودیت نیست.`,429);throw new AppError(msg,502)}}
async function deployWorker(token,accountId,scriptName,kvId,code,version){const fd=new FormData();fd.append("metadata",JSON.stringify({main_module:"worker.js",compatibility_date:"2026-08-24",bindings:[{type:"kv_namespace",name:"kv",namespace_id:kvId}],annotations:{"workers/message":`JavidPanel ${version}`,"workers/tag":`javid-${version}`}}));fd.append("worker.js",new Blob([code],{type:"application/javascript+module"}),"worker.js");await cf(token,`/accounts/${accountId}/workers/scripts/${scriptName}`,{method:"PUT",body:fd});await cf(token,`/accounts/${accountId}/workers/scripts/${scriptName}/subdomain`,{method:"POST",body:JSON.stringify({enabled:true,previews_enabled:false}),headers:{"content-type":"application/json"}})}
async function deleteWorker(token,accountId,scriptName){try{await cf(token,`/accounts/${accountId}/workers/scripts/${scriptName}`,{method:"DELETE"});return true}catch{return false}}

function releaseKey(v,s){return `release:${v}:${s}`}
async function getRelease(env,version){const meta=await kvJson(env,releaseKey(version,"meta"),null);if(!meta)return null;const code=await env.BOT_KV.get(releaseKey(version,"artifact"));return code?{...meta,code}:null}
async function getPublicRelease(env){const p=await kvJson(env,"release:public",null);if(!p?.version)throw new AppError("هنوز نسخه عمومی برای نصب منتشر نشده است.",409);const r=await getRelease(env,p.version);if(!r)throw new AppError("فایل نسخه عمومی پیدا نشد.",500);return r}
async function getBetaRelease(env){const p=await kvJson(env,"release:beta",null);if(!p?.version)throw new AppError("نسخه Beta وجود ندارد.",409);const r=await getRelease(env,p.version);if(!r)throw new AppError("فایل نسخه Beta پیدا نشد.",500);return r}
async function stageRelease(env,form){
 const file=form.get("artifact");
 if(!file||typeof file.text!=="function")throw new AppError("فایل کامل Worker مبهم‌شده را انتخاب کنید.",400);
 const filename=String(file.name||"");
 let version=String(form.get("version")||"").trim().replace(/^v/i,"");
 if(!version){const m=filename.match(/(?:^|[-_])v?(\d+\.\d+\.\d+(?:[-+][0-9A-Za-z.-]+)?)/i);if(m)version=m[1]}
 if(!/^\d+\.\d+\.\d+(?:[-+][0-9A-Za-z.-]+)?$/.test(version))throw new AppError("شماره نسخه را وارد کنید یا در نام فایل قرار دهید؛ مثال: JavidPanel-v0.5.5-worker.obf.js",400);
 if(String(form.get("confirmedManualObfuscation")||"")!=="1")throw new AppError("تأیید کنید که فایل کامل Worker را به‌صورت دستی مبهم کرده‌اید.",400);
 const artifact=await file.text();
 const size=enc.encode(artifact).byteLength;
 if(size<50000)throw new AppError("فایل Worker بیش از حد کوچک است و به‌عنوان Build کامل پذیرفته نشد.",400);
 if(size>20*1024*1024)throw new AppError("فایل Worker از سقف ایمنی 20MiB بزرگ‌تر است.",400);
 const obviousRaw=artifact.includes("JavidPanel Professional UI Layer")&&artifact.includes("function javid")&&artifact.includes("JAVID_UI_VERSION");
 if(obviousRaw)throw new AppError("این فایل شبیه Worker خام و خوانا است. ابتدا کل فایل را در Obfuscator.io مبهم کنید و خروجی را Upload کنید.",400);
 const meta={version,notes:String(form.get("notes")||"").slice(0,10000),status:"beta",channel:"beta",createdAt:nowIso(),sourceFile:filename,artifactSha256:await sha256Hex(artifact),size,obfuscated:true,obfuscation:"manual-full-worker",installScope:"admin-only"};
 await env.BOT_KV.put(releaseKey(version,"artifact"),artifact);
 await setJson(env,releaseKey(version,"meta"),meta);
 await indexAdd(env,"releases:index",version);
 await setJson(env,"release:beta",meta);
 return meta
}
async function promoteRelease(env,version){const r=await getRelease(env,version);if(!r)throw new AppError("Release پیدا نشد.",404);const got=await sha256Hex(r.code);if(got!==r.artifactSha256)throw new AppError("SHA-256 فایل Release معتبر نیست.",500);const meta={...r};delete meta.code;meta.status="public";meta.channel="stable";meta.installScope="public";meta.promotedAt=nowIso();await setJson(env,releaseKey(version,"meta"),meta);await setJson(env,"release:public",meta);return meta}
async function listReleases(env){const ids=await kvJson(env,"releases:index",[]);const out=[];for(const id of ids.slice(0,50)){const m=await kvJson(env,releaseKey(id,"meta"),null);if(m)out.push(m)}return out}
async function deleteRelease(env,version){version=String(version||"").trim().replace(/^v/i,"");if(!version)throw new AppError("شماره نسخه نامعتبر است.",400);const meta=await kvJson(env,releaseKey(version,"meta"),null);if(!meta)throw new AppError("Release پیدا نشد.",404);await env.BOT_KV.delete(releaseKey(version,"artifact"));await env.BOT_KV.delete(releaseKey(version,"meta"));await indexRemove(env,"releases:index",version);const beta=await kvJson(env,"release:beta",null);if(beta?.version===version)await env.BOT_KV.delete("release:beta");const pub=await kvJson(env,"release:public",null);if(pub?.version===version)await env.BOT_KV.delete("release:public");return {version,deleted:true,wasPublic:meta.status==="public"}}
async function withHeavyOperation(env,key,label,fn){const lockKey="oplock:"+key,cur=await kvJson(env,lockKey,null),ttl=15*60*1000;if(cur?.startedAt&&Date.now()-Date.parse(cur.startedAt)<ttl)throw new AppError("یک عملیات سنگین دیگر در حال انجام است: "+(cur.label||label)+". تا پایان همان عملیات صبر کنید.",409);const marker={id:uuid(),key,label,startedAt:nowIso()};await setJson(env,lockKey,marker,{expirationTtl:900});try{return await fn(marker)}finally{const latest=await kvJson(env,lockKey,null);if(latest?.id===marker.id)await env.BOT_KV.delete(lockKey)}}

async function createPanel(env,ownerType,userId,token,account,release,opts={}){const cfg=await getConfig(env);if(ownerType==="telegram"){const existing=await userPanels(env,userId);if(existing.length>=Number(cfg.maxPanelsPerUser||1))throw new AppError(`حداکثر تعداد نصب برای حساب شما ${cfg.maxPanelsPerUser} است.`,409)}const suffix=randHex(4);const id=randHex(12);const scriptName=safeName(opts.scriptName||`javid-panel-${String(userId).slice(-6)}-${suffix}`);const kv=await createKv(token,account.id,`JavidPanel_${String(userId).replace(/[^a-zA-Z0-9]/g,"")}_${suffix}`);try{const securePath=randomPath();const password=strongPassword();const sub=await cfSubdomain(token,account.id);const host=`${scriptName}.${sub.subdomain}.workers.dev`;const embed={accID:randHex(8),accEmail:"admin",apiToken:"",vlUUID:uuid(),trPass:randHex(12),securePath,proxyIpMode:"proxyip",proxyIPs:[],prefixes:[],mainDomain:host,fallback:"www.speedtest.net",dohUrl:"https://cloudflare-dns.com/dns-query"};const licenseMarker={id,source:ownerType==="telegram"?"telegram-installer":"admin-direct-test",issuedAt:nowIso(),version:release.version,issuer:"JavidPanel Installer"};await kvPut(token,account.id,kv.id,"pwd",password);await kvPut(token,account.id,kv.id,"javid_embed",JSON.stringify(embed));await kvPut(token,account.id,kv.id,"javid_users","[]");await kvPut(token,account.id,kv.id,"javid_install_license",JSON.stringify(licenseMarker));await deployWorker(token,account.id,scriptName,kv.id,release.code,release.version);const panel={id,userId:String(userId),ownerType,accountId:account.id,accountName:account.name||"",scriptName,kvId:kv.id,host,panelUrl:`https://${host}/${securePath}/panel`,version:release.version,releaseChannel:release.channel||release.status,createdAt:nowIso(),updatedAt:nowIso(),autoUpdate:false,status:"active",cfToken:await seal(env,token),panelPassword:await seal(env,password),securePath};await setJson(env,"panel:"+id,panel);await indexAdd(env,"panels:index",id);if(ownerType==="telegram"){const up=await kvJson(env,"userpanels:"+userId,[]);if(!up.includes(id)){up.unshift(id);await setJson(env,"userpanels:"+userId,up)}const u=await kvJson(env,"user:"+userId,null);if(u){u.installCount=(u.installCount||0)+1;await setJson(env,"user:"+userId,u)}}return {...panel,password}}catch(e){await deleteKv(token,account.id,kv.id);throw e}}
async function updatePanel(env,p,release){const token=await openSeal(env,p.cfToken);await deployWorker(token,p.accountId,p.scriptName,p.kvId,release.code,release.version);await kvPut(token,p.accountId,p.kvId,"javid_install_license",JSON.stringify({id:p.id,source:"installer-update",issuedAt:p.createdAt,updatedAt:nowIso(),version:release.version,issuer:"JavidPanel Installer"}));p.version=release.version;p.releaseChannel=release.channel||release.status;p.updatedAt=nowIso();p.status="active";p.lastError="";await setJson(env,"panel:"+p.id,p);return p}
async function reinstallPanel(env,p,release){return updatePanel(env,p,release)}
async function cleanReinstallPanel(env,p,release){const token=await openSeal(env,p.cfToken);const old={scriptName:p.scriptName,kvId:p.kvId};const suffix=randHex(4);const scriptName=safeName(`javid-panel-${String(p.userId).slice(-6)}-${suffix}`);const kv=await createKv(token,p.accountId,`JavidPanel_clean_${String(p.userId).replace(/[^a-zA-Z0-9]/g,"")}_${suffix}`);try{const securePath=randomPath();const password=strongPassword();const sub=await cfSubdomain(token,p.accountId);const host=`${scriptName}.${sub.subdomain}.workers.dev`;const embed={accID:randHex(8),accEmail:"admin",apiToken:"",vlUUID:uuid(),trPass:randHex(12),securePath,proxyIpMode:"proxyip",proxyIPs:[],prefixes:[],mainDomain:host,fallback:"www.speedtest.net",dohUrl:"https://cloudflare-dns.com/dns-query"};await kvPut(token,p.accountId,kv.id,"pwd",password);await kvPut(token,p.accountId,kv.id,"javid_embed",JSON.stringify(embed));await kvPut(token,p.accountId,kv.id,"javid_users","[]");await kvPut(token,p.accountId,kv.id,"javid_install_license",JSON.stringify({id:p.id,source:"clean-reinstall",issuedAt:nowIso(),version:release.version,issuer:"JavidPanel Installer"}));await deployWorker(token,p.accountId,scriptName,kv.id,release.code,release.version);const workerDeleted=await deleteWorker(token,p.accountId,old.scriptName);const kvDeleted=await deleteKv(token,p.accountId,old.kvId);p.scriptName=scriptName;p.kvId=kv.id;p.host=host;p.panelUrl=`https://${host}/${securePath}/panel`;p.panelPassword=await seal(env,password);p.securePath=securePath;p.version=release.version;p.releaseChannel=release.channel||release.status;p.status="active";p.updatedAt=nowIso();p.cleanReinstalledAt=nowIso();p.lastCleanup={workerDeleted,kvDeleted};await setJson(env,"panel:"+p.id,p);return {...p,password}}catch(e){await deleteWorker(token,p.accountId,scriptName);await deleteKv(token,p.accountId,kv.id);throw e}}
async function removePanel(env,p){const token=await openSeal(env,p.cfToken);const workerDeleted=await deleteWorker(token,p.accountId,p.scriptName);const kvDeleted=await deleteKv(token,p.accountId,p.kvId);await env.BOT_KV.delete("panel:"+p.id);await indexRemove(env,"panels:index",p.id);if(p.ownerType==="telegram")await indexRemove(env,"userpanels:"+p.userId,p.id);return {workerDeleted,kvDeleted}}

async function renderMyPanels(env,userId,chatId){const ps=await userPanels(env,userId);if(!ps.length)return sendText(env,chatId,"هنوز پنلی نصب نکردی. اگر آماده‌ای، روی «نصب پنل جدید» بزن تا مرحله‌به‌مرحله جلو برویم.",await mainKeyboard(env));let pub=null;try{pub=await getPublicRelease(env)}catch{};for(const p of ps){const outdated=pub&&p.version!==pub.version;const rows=[];if(outdated)rows.push([{text:`⬆️ بروزرسانی به نسخه ${pub.version}`,callback_data:"upd:"+p.id}]);rows.push([{text:"🔁 نصب دوباره همین پنل",callback_data:"rei:"+p.id},{text:"🧼 نصب تمیز",callback_data:"clnq:"+p.id}]);rows.push([{text:"🗑 حذف پنل",callback_data:"delq:"+p.id},{text:"🌐 باز کردن پنل",url:p.panelUrl}]);await sendText(env,chatId,`<b>🧩 پنل من</b>\nنسخه: <code>${p.version}</code>${outdated?` ← نسخه جدید ${pub.version}`:""}\nوضعیت: ${p.status==="active"?"✅ فعال":"⚠️ نیازمند بررسی"}\n\n«نصب دوباره» همان نشانی و اطلاعات فعلی را نگه می‌دارد. «نصب تمیز» یک پنل تازه با نشانی و رمز تازه می‌سازد و اطلاعات داخل پنل قبلی را منتقل نمی‌کند.`,{inline_keyboard:rows})}}

async function sendGuide(env,chatId){return sendText(env,chatId,`<b>📚 راهنمای کامل — بخش ۱ از ۵</b>\n\n<b>پنل جاوید چیست؟</b>\nپنل جاوید یک پنل رایگان برای استفاده شخصی و خانوادگی است. این پروژه برای فروش سرویس یا راه‌اندازی کسب‌وکار فروش اشتراک طراحی نشده و فروش آن مجاز نیست.\n\n<b>کلادفلیر چیست؟</b>\nکلادفلیر یک سرویس اینترنتی است که بخشی به نام «ورکر» دارد. ورکر یک برنامه کوچک است که روی شبکه کلادفلیر اجرا می‌شود و لازم نیست برای آن سرور شخصی جداگانه تهیه کنی. پنل جاوید روی همین ورکر اجرا می‌شود.\n\nبرای ادامه راهنما روی دکمه زیر بزن.`,{inline_keyboard:[[{text:"ادامه: ساخت حساب کلادفلیر",callback_data:"docs2"}]]})}
async function sendGuide2(env,chatId){return sendText(env,chatId,`<b>📚 راهنمای کامل — بخش ۲ از ۵</b>\n\n<b>ساخت حساب کلادفلیر</b>\n۱) روی دکمه «ساخت حساب کلادفلیر» بزن.\n۲) در صفحه بازشده، نشانی ایمیل و یک رمز قوی وارد کن.\n۳) حساب را بساز.\n۴) ایمیلی که کلادفلیر برایت می‌فرستد باز کن و نشانی ایمیل را تأیید کن.\n۵) دوباره وارد حساب کلادفلیر شو.\n\nبرای شروع معمولاً همان حساب رایگان کافی است و برای نصب پنل جاوید لازم نیست دامنه‌ای به حساب اضافه کنی.`,{inline_keyboard:[[{text:"🆕 ساخت حساب کلادفلیر",url:CLOUDFLARE_SIGNUP_URL}],[{text:"ادامه: ساخت توکن دسترسی",callback_data:"docs3"}]]})}
async function sendGuide3(env,chatId){return sendText(env,chatId,`<b>📚 راهنمای کامل — بخش ۳ از ۵</b>\n\n<b>ساخت توکن دسترسی</b>\nتوکن دسترسی مثل یک کلید موقت است که به ربات اجازه می‌دهد فقط کارهای لازم برای نصب پنل را در حساب کلادفلیر انجام دهد.\n\n۱) روی دکمه «ساخت توکن دسترسی کلادفلیر» بزن.\n۲) اگر کلادفلیر از تو خواست وارد حساب شو، همان حسابی را که ساختی باز کن.\n۳) دسترسی‌های لازم از قبل در لینک آماده شده‌اند.\n۴) ساخت توکن را تأیید کن.\n۵) رشته‌ای که کلادفلیر در پایان نشان می‌دهد کامل کپی کن.\n۶) به ربات برگرد و «نصب پنل جدید» را بزن.\n۷) توکن را در یک پیام برای ربات بفرست.\n\nتوکن خودت را برای هیچ شخص دیگری ارسال نکن.`,{inline_keyboard:[[{text:"🔐 ساخت توکن دسترسی کلادفلیر",url:TOKEN_TEMPLATE_URL}],[{text:"ادامه: نصب پنل",callback_data:"docs4"}]]})}
async function sendGuide4(env,chatId){return sendText(env,chatId,`<b>📚 راهنمای کامل — بخش ۴ از ۵</b>\n\n<b>نصب پنل</b>\nبعد از فرستادن توکن، ربات اعتبار آن را بررسی می‌کند. اگر بیش از یک حساب در کلادفلیر داشته باشی، از تو می‌خواهد حساب موردنظر را انتخاب کنی.\n\nبعد از آن همه کارها خودکار انجام می‌شود: فضای ذخیره‌سازی ساخته می‌شود، ورکر پنل ایجاد می‌شود، مسیر ورود امن ساخته می‌شود و یک رمز قوی برای مدیریت پنل تعیین می‌شود.\n\nدر پایان، ربات نشانی ورود به پنل و رمز مدیریت را به تو می‌دهد. رمز را در جای امن نگه دار.`,{inline_keyboard:[[{text:"ادامه: استفاده از پنل",callback_data:"docs5"}]]})}
async function sendGuide5(env,chatId){return sendText(env,chatId,`<b>📚 راهنمای کامل — بخش ۵ از ۵</b>\n\n<b>استفاده از پنل جاوید</b>\nپس از ورود به پنل، بخش «کاربران» را باز کن. برای هر عضو خانواده یا دستگاه می‌توانی یک کاربر جدا بسازی.\n\nهنگام ساخت کاربر می‌توانی نام، مدت اعتبار و در صورت نیاز محدودیت حجم تعیین کنی. سپس لینک اشتراک همان کاربر را کپی کن و فقط برای همان شخص بفرست.\n\nهر کاربر صفحه مخصوص خودش را دارد و می‌تواند لینک مناسب برنامه‌اش را ببیند و کپی کند.\n\nدر بخش «پنل‌های من» همین ربات هم می‌توانی پنل را بروزرسانی، دوباره نصب، به‌صورت تمیز نصب یا حذف کنی.\n\n<b>یادآوری مهم</b>\nپنل جاوید رایگان است و برای استفاده شخصی و خانوادگی ساخته شده است. فروش پنل، فروش نسخه تغییرنام‌داده‌شده یا معرفی آن به‌عنوان محصول پولی مجاز نیست.\n\nکانال رسمی: @javidpnl`,await mainKeyboard(env))}

async function onMessage(env,msg){const cfg=await getConfig(env);const u=await touchUser(env,msg.from||{});const chatId=msg.chat.id,textMsg=String(msg.text||"").trim();if(u.blocked)return sendText(env,chatId,"⛔ دسترسی این حساب به ربات غیرفعال شده است.");if(!cfg.botEnabled)return sendText(env,chatId,"🛠 ربات موقتاً در حال نگهداری است. کمی بعد دوباره تلاش کن.");if(!(await membershipPrompt(env,chatId,u.id)))return;if(textMsg==="/start"||textMsg==="/menu"){await env.BOT_KV.delete("state:"+u.id);return sendText(env,chatId,`<b>پنل جاوید</b> ✨\n\n${cfg.welcomeText}\n\nپنل جاوید رایگان است و برای استفاده شخصی و خانوادگی ساخته شده. برای شروع می‌توانی راهنمای کامل را بخوانی یا مستقیم نصب را آغاز کنی.`,await mainKeyboard(env))}const st=await kvJson(env,"state:"+u.id,null);if(st?.step==="await_token"){if(textMsg.length<30)return sendText(env,chatId,"این متن شبیه توکن دسترسی کلادفلیر نیست. توکن کامل را کپی کن و دوباره بفرست.");try{await sendText(env,chatId,"⏳ توکن را بررسی می‌کنم…");await verifyCfToken(textMsg);const ac=await cfAccounts(textMsg);if(!Array.isArray(ac)||!ac.length)throw new AppError("حساب کلادفلیر پیدا نشد.",400);const sealed=await seal(env,textMsg);if(ac.length===1){await env.BOT_KV.delete("state:"+u.id);const rel=await getPublicRelease(env);await sendText(env,chatId,"⚙️ توکن درست است. الان پنل را می‌سازم؛ معمولاً چند ثانیه زمان می‌برد…");const p=await createPanel(env,"telegram",u.id,textMsg,ac[0],rel);return sendText(env,chatId,`✅ <b>پنلت آماده شد</b>\n\n🌐 <a href="${p.panelUrl}">ورود به پنل جاوید</a>\n👤 نام کاربری: <code>admin</code>\n🔑 رمز مدیریت: <code>${p.password}</code>\n📦 نسخه: <code>${p.version}</code>\n\nرمز را در جای امن نگه دار. از بخش «پنل‌های من» می‌توانی پنل را بروزرسانی، دوباره نصب یا حذف کنی.`,await mainKeyboard(env))}await setJson(env,"state:"+u.id,{step:"choose_account",token:sealed,accounts:ac.map(a=>({id:a.id,name:a.name}))},{expirationTtl:900});return sendText(env,chatId,"توکن درست است ✅ حالا حساب کلادفلیر موردنظر را انتخاب کن:",{inline_keyboard:ac.slice(0,10).map(a=>[{text:a.name||"حساب کلادفلیر",callback_data:"acc:"+a.id}])})}catch(e){return sendText(env,chatId,"❌ "+friendlyUserError(e))}}return sendText(env,chatId,"برای ادامه از دکمه‌های زیر استفاده کن 👇",await mainKeyboard(env))}

async function onCallback(env,q){await answerCb(env,q.id);const u=await touchUser(env,q.from||{});if(u.blocked)return;const d=String(q.data||""),chatId=q.message?.chat?.id||q.from.id;if(d==="checkjoin"){const st=await membershipStatus(env,u.id);if(st.ok)return sendText(env,chatId,"✅ عضویت تأیید شد. خوش آمدی؛ از خانه ربات ادامه بده 👇",await mainKeyboard(env));return membershipPrompt(env,chatId,u.id)}if(d==="noop")return;if(d==="menu"){await env.BOT_KV.delete("state:"+u.id);return sendText(env,chatId,"🏠 خانه ربات",await mainKeyboard(env))}if(!(await membershipPrompt(env,chatId,u.id)))return;if(d==="install"){try{await getPublicRelease(env)}catch(e){return sendText(env,chatId,"⏳ هنوز نسخه عمومی آماده نصب نیست. کمی بعد دوباره تلاش کن.",await mainKeyboard(env))}await setJson(env,"state:"+u.id,{step:"await_token"},{expirationTtl:900});return sendText(env,chatId,"<b>🚀 نصب پنل جدید</b>\n\nاگر هنوز حساب کلادفلیر نداری، اول آن را بساز و ایمیلت را تأیید کن. بعد با دکمه دوم توکن دسترسی را بساز.\n\nپس از ساخت توکن، آن را کامل کپی کن و همینجا در یک پیام بفرست.",{inline_keyboard:[[{text:"🆕 ساخت حساب کلادفلیر",url:CLOUDFLARE_SIGNUP_URL}],[{text:"🔐 ساخت توکن دسترسی کلادفلیر",url:TOKEN_TEMPLATE_URL}],[{text:"📚 راهنمای قدم‌به‌قدم",callback_data:"docs"}]]})}if(d==="mypanels")return renderMyPanels(env,u.id,chatId);if(d==="docs")return sendGuide(env,chatId);if(d==="docs2")return sendGuide2(env,chatId);if(d==="docs3")return sendGuide3(env,chatId);if(d==="docs4")return sendGuide4(env,chatId);if(d==="docs5")return sendGuide5(env,chatId);if(d==="about")return sendText(env,chatId,`<b>ℹ️ درباره پنل جاوید</b>\n\nپنل جاوید یک پروژه رایگان برای استفاده شخصی و خانوادگی است. نصب رسمی آن از همین ربات انجام می‌شود.\n\nاین پروژه برای فروش سرویس، فروش پنل یا ساخت نسخه پولی و تغییرنام‌داده‌شده طراحی نشده و فروش آن مجاز نیست.\n\n🤖 ربات رسمی:\n${OFFICIAL_BOT_URL}\n\n📣 کانال رسمی:\n${OFFICIAL_CHANNEL_URL}\n\n🌐 گیت‌هاب رسمی:\n${REPO_URL}`,{inline_keyboard:[[{text:"📣 کانال رسمی پنل جاوید",url:OFFICIAL_CHANNEL_URL}],[{text:"🌐 گیت‌هاب پروژه",url:REPO_URL}]]});if(d.startsWith("acc:")){const st=await kvJson(env,"state:"+u.id,null);if(!st||st.step!=="choose_account")return sendText(env,chatId,"این درخواست منقضی شده است. از خانه ربات نصب را دوباره شروع کن.",await mainKeyboard(env));const account=st.accounts.find(a=>a.id===d.slice(4));if(!account)return sendText(env,chatId,"حساب پیدا نشد. نصب را دوباره شروع کن.");try{const token=await openSeal(env,st.token);await env.BOT_KV.delete("state:"+u.id);const rel=await getPublicRelease(env);await sendText(env,chatId,"⚙️ حساب انتخاب شد. در حال ساخت پنل…");const p=await createPanel(env,"telegram",u.id,token,account,rel);return sendText(env,chatId,`✅ <b>پنلت آماده شد</b>\n\n🌐 <a href="${p.panelUrl}">ورود به پنل جاوید</a>\n👤 نام کاربری: <code>admin</code>\n🔑 رمز مدیریت: <code>${p.password}</code>\n📦 نسخه: <code>${p.version}</code>\n\nرمز را در جای امن نگه دار.`,await mainKeyboard(env))}catch(e){return sendText(env,chatId,"❌ "+friendlyUserError(e),await mainKeyboard(env))}}const parts=d.split(":"),act=parts[0],pid=parts[1];if(["upd","rei","clnq","clny","delq","dely"].includes(act)&&pid){const p=await kvJson(env,"panel:"+pid,null);if(!p||p.userId!==u.id)return sendText(env,chatId,"پنل پیدا نشد یا متعلق به این حساب نیست.");if(act==="clnq")return sendText(env,chatId,"🧼 <b>نصب تمیز</b>\n\nیک پنل تازه با نشانی و رمز تازه ساخته می‌شود. اطلاعات کاربران و تنظیمات پنل قبلی منتقل نمی‌شود. اگر مطمئنی ادامه بده.",{inline_keyboard:[[{text:"بله، نصب تمیز انجام شود",callback_data:"clny:"+pid}],[{text:"انصراف",callback_data:"mypanels"}]]});if(act==="delq")return sendText(env,chatId,"🗑 با حذف پنل، ورکر و فضای ذخیره‌سازی آن پاک می‌شود و این کار قابل بازگشت نیست. مطمئنی؟",{inline_keyboard:[[{text:"بله، کامل حذف شود",callback_data:"dely:"+pid}],[{text:"انصراف",callback_data:"mypanels"}]]});try{const rel=await getPublicRelease(env);if(act==="upd"){await sendText(env,chatId,"⬆️ بروزرسانی را شروع کردم…");await updatePanel(env,p,rel);return sendText(env,chatId,`✅ پنل به نسخه <code>${rel.version}</code> بروزرسانی شد.`,await mainKeyboard(env))}if(act==="rei"){await sendText(env,chatId,"🔁 در حال نصب دوباره روی همان پنل…");await reinstallPanel(env,p,rel);return sendText(env,chatId,"✅ نصب دوباره انجام شد و نشانی و اطلاعات قبلی حفظ شدند.",await mainKeyboard(env))}if(act==="clny"){await sendText(env,chatId,"🧼 در حال ساخت پنل تازه…");const np=await cleanReinstallPanel(env,p,rel);return sendText(env,chatId,`✅ <b>نصب تمیز انجام شد</b>\n\n🌐 <a href="${np.panelUrl}">نشانی جدید پنل</a>\n👤 نام کاربری: <code>admin</code>\n🔑 رمز مدیریت: <code>${np.password}</code>\n\nنشانی قبلی حذف شده است.`,await mainKeyboard(env))}if(act==="dely"){await removePanel(env,p);return sendText(env,chatId,"✅ پنل و اطلاعات مربوط به نصب آن حذف شد.",await mainKeyboard(env))}}catch(e){return sendText(env,chatId,"❌ "+friendlyUserError(e),await mainKeyboard(env))}}if(d.startsWith("upmenu:"))return renderMyPanels(env,u.id,chatId)}

async function telegramWebhook(req,env){const sec=await getSecret(env,"TELEGRAM_WEBHOOK_SECRET");if(sec&&req.headers.get("X-Telegram-Bot-Api-Secret-Token")!==sec)return text("Forbidden",403);const upd=await req.json();if(upd.message)await onMessage(env,upd.message);if(upd.callback_query)await onCallback(env,upd.callback_query);return text("OK")}

async function configureTelegram(req,env){requireMaster(env);const b=await req.json();const candidate=String(b.botToken||"").trim();if(candidate){const old=await getSecret(env,"BOT_TOKEN");await setSecret(env,"BOT_TOKEN",candidate);try{await tg(env,"getMe",{})}catch(e){await setSecret(env,"BOT_TOKEN",old);throw e}}let sec=await getSecret(env,"TELEGRAM_WEBHOOK_SECRET");if(!sec){sec=randHex(24);await setSecret(env,"TELEGRAM_WEBHOOK_SECRET",sec)}if(!await getSecret(env,"BOT_TOKEN"))throw new AppError("Bot Token را وارد کنید.",400);const me=await tg(env,"getMe",{});const hookUrl=new URL(req.url).origin+"/telegram/webhook";const hook=await tg(env,"setWebhook",{url:hookUrl,secret_token:sec,allowed_updates:["message","callback_query"],drop_pending_updates:!!b.dropPending});await setJson(env,"telegram:profile",{id:me.id,username:me.username||"",firstName:me.first_name||"",webhookUrl:hookUrl,configuredAt:nowIso()});return {profile:await kvJson(env,"telegram:profile",{}),webhook:hook}}
async function telegramStatus(env){const profile=await kvJson(env,"telegram:profile",{});let webhook=null,me=null;if(await getSecret(env,"BOT_TOKEN")){try{me=await tg(env,"getMe",{});webhook=await tg(env,"getWebhookInfo",{})}catch(e){webhook={error:String(e.message||e)}}}return {profile,me,webhook}}

async function queueBroadcast(env,{text:body,photo="",buttonText="",buttonUrl="",targets=null,type="general",version=""}){if(!String(body||"").trim())throw new AppError("متن پیام خالی است.",400);const id=randHex(8);await setJson(env,"broadcast:"+id,{id,text:String(body),photo:String(photo||""),buttonText:String(buttonText||""),buttonUrl:String(buttonUrl||""),targets:Array.isArray(targets)?targets:null,type,version,offset:0,status:"queued",createdAt:nowIso()});await indexAdd(env,"broadcast:index",id);return id}
async function notifyRelease(env,version){const r=await getRelease(env,version);if(!r||r.status!=="public")throw new AppError("فقط نسخه Public قابل اطلاع‌رسانی است.",409);const ids=await kvJson(env,"panels:index",[]);const targets=new Set();for(const id of ids){const p=await kvJson(env,"panel:"+id,null);if(p?.ownerType==="telegram"&&p.version!==version)targets.add(p.userId)}if(!targets.size)return {queued:false,count:0};const body=`✨ <b>نسخه جدید پنل جاوید منتشر شد</b>\n\nنسخه <code>${version}</code> آماده است. اگر پنلت قدیمی‌تر است، می‌توانی از داخل همین ربات آن را بروزرسانی کنی.\n\nبرای دیدن پنل‌ها و شروع بروزرسانی روی دکمه زیر بزن 👇`;const id=await queueBroadcast(env,{text:body,targets:[...targets],type:"release",version});return {queued:true,count:targets.size,id}}
async function processBroadcast(env){const ids=await kvJson(env,"broadcast:index",[]),allUsers=await kvJson(env,"users:index",[]),cfg=await getConfig(env);for(const id of ids){const b=await kvJson(env,"broadcast:"+id,null);if(!b||b.status==="done")continue;const source=b.targets||allUsers;const batch=source.slice(b.offset,b.offset+Number(cfg.broadcastBatch||25));for(const uid of batch){const u=await kvJson(env,"user:"+uid,null);if(!u||u.blocked)continue;let markup;if(b.type==="release")markup={inline_keyboard:[[{text:`⬆️ مشاهده و بروزرسانی به ${b.version}`,callback_data:"upmenu:"+b.version}],[{text:"🌐 گیت‌هاب پروژه",url:REPO_URL}]]};else if(b.buttonText&&b.buttonUrl)markup={inline_keyboard:[[{text:b.buttonText,url:b.buttonUrl}]]};try{b.photo?await sendPhoto(env,uid,b.photo,b.text,markup):await sendText(env,uid,b.text,markup)}catch(e){console.log("broadcast",uid,e)} }b.offset+=batch.length;if(b.offset>=source.length)b.status="done";await setJson(env,"broadcast:"+id,b);break}}

async function ghRequest(env,path,init={}){const token=await getSecret(env,"GITHUB_TOKEN");if(!token)throw new AppError("GitHub Token در Installer تنظیم نشده است.",400);const h=new Headers(init.headers||{});h.set("authorization","Bearer "+token);h.set("accept","application/vnd.github+json");h.set("x-github-api-version","2022-11-28");h.set("user-agent","JavidPanel-Installer/"+VERSION);const r=await fetch("https://api.github.com"+path,{...init,headers:h});const txt=await r.text();let d={};try{d=JSON.parse(txt)}catch{d={message:txt}}if(!r.ok)throw new AppError(`GitHub HTTP ${r.status}: ${d.message||txt.slice(0,300)}`,502);return d}
async function ghPutContent(env,repo,branch,path,content,message){let sha="";try{const cur=await ghRequest(env,`/repos/${repo}/contents/${path}?ref=${encodeURIComponent(branch)}`);sha=cur.sha||""}catch(e){if(!String(e.message).includes("404"))throw e}const payload={message,content:btoa(unescape(encodeURIComponent(content))),branch};if(sha)payload.sha=sha;return ghRequest(env,`/repos/${repo}/contents/${path}`,{method:"PUT",headers:{"content-type":"application/json"},body:JSON.stringify(payload)})}
async function publishGitHub(env,version){const cfg=await getConfig(env);const r=await getRelease(env,version);if(!r||r.status!=="public")throw new AppError("برای GitHub فقط نسخه Public قابل انتشار است.",409);const repo=cfg.githubRepo||DEFAULT_REPO,branch=cfg.githubBranch||"main",workerPath="dist/JavidPanel.worker.js";const workerRaw=`https://raw.githubusercontent.com/${repo}/${branch}/${workerPath}`;const manifest={version:r.version,status:"public",channel:"stable",workerUrl:workerRaw,sha256:r.artifactSha256,size:r.size,releasedAt:r.promotedAt||nowIso(),obfuscated:true,obfuscator:"manual-obfuscator.io",installerMinVersion:VERSION};await ghPutContent(env,repo,branch,workerPath,r.code,`release: JavidPanel v${version} worker`);await ghPutContent(env,repo,branch,"dist/manifest.json",JSON.stringify(manifest,null,2)+"\n",`release: JavidPanel v${version} manifest`);const meta={...r};delete meta.code;meta.githubPublishedAt=nowIso();await setJson(env,releaseKey(version,"meta"),meta);const pub=await kvJson(env,"release:public",null);if(pub?.version===version)await setJson(env,"release:public",meta);return {meta,manifest}}

async function dashboardData(env){const userIds=await kvJson(env,"users:index",[]),panelIds=await kvJson(env,"panels:index",[]),cfg=await getConfig(env),beta=await kvJson(env,"release:beta",null),pub=await kvJson(env,"release:public",null),releases=await listReleases(env),secrets=await secretState(env);const users=[];for(const id of userIds.slice(0,300)){const u=await kvJson(env,"user:"+id,null);if(u)users.push(u)}const panels=[];for(const id of panelIds.slice(0,300)){const p=await kvJson(env,"panel:"+id,null);if(p){const x={...p};delete x.cfToken;delete x.panelPassword;panels.push(x)}}return {ok:true,version:VERSION,config:cfg,betaRelease:beta,publicRelease:pub,releases,secrets,users,panels,stats:{users:userIds.length,panels:panelIds.length,activePanels:panels.filter(p=>p.status==="active").length,beta:beta?.version||"—",public:pub?.version||"—"},telegram:await telegramStatus(env)}}

async function adminApi(req,env,path){if(!(await isAdmin(req,env)))return json({ok:false,error:"Unauthorized"},401);try{
 if(path==="dashboard"&&req.method==="GET")return json(await dashboardData(env));
 if(path==="config"&&req.method==="POST"){const b=await req.json(),c=await getConfig(env);if(b.maxPanelsPerUser!=null)c.maxPanelsPerUser=clampInt(b.maxPanelsPerUser,1,50,2);if(typeof b.botEnabled==="boolean")c.botEnabled=b.botEnabled;if(typeof b.forcedJoinEnabled==="boolean")c.forcedJoinEnabled=b.forcedJoinEnabled;if(Array.isArray(b.forcedJoinChats))c.forcedJoinChats=normalizeForcedChats(b.forcedJoinChats);for(const k of ["welcomeText","supportText","buttonInstall","buttonPanels","buttonDocs","buttonAbout","githubRepo","githubBranch"]){if(b[k]!=null)c[k]=String(b[k]).trim().slice(0,k.startsWith("button")?64:1000)}await setJson(env,"config",c);return json({ok:true,config:c})}
 if(path==="secrets"&&req.method==="POST"){const b=await req.json();if(b.GITHUB_TOKEN!==undefined)await setSecret(env,"GITHUB_TOKEN",String(b.GITHUB_TOKEN||"").trim());return json({ok:true,secrets:await secretState(env)})}
 if(path==="telegram/setup"&&req.method==="POST")return json({ok:true,...await configureTelegram(req,env)});
 if(path==="telegram/status"&&req.method==="GET")return json({ok:true,...await telegramStatus(env)});
 if(path==="telegram/delete-webhook"&&req.method==="POST"){await tg(env,"deleteWebhook",{drop_pending_updates:false});return json({ok:true})}
 if(path==="user-toggle"&&req.method==="POST"){const b=await req.json(),id=String(b.userId||"");const u=await kvJson(env,"user:"+id,null);if(!u)return json({ok:false,error:"User not found"},404);u.blocked=!!b.blocked;await setJson(env,"user:"+id,u);return json({ok:true,user:u})}
 if(path==="broadcast"&&req.method==="POST"){const b=await req.json();return json({ok:true,id:await withHeavyOperation(env,"broadcast","ارسال گروهی",()=>queueBroadcast(env,b))})}
 if(path==="release/stage"&&req.method==="POST"){const form=await req.formData();return json({ok:true,release:await withHeavyOperation(env,"release-stage","آپلود نسخه",()=>stageRelease(env,form))})}
 if(path==="release/promote"&&req.method==="POST"){const b=await req.json();return json({ok:true,release:await withHeavyOperation(env,"release-promote","Public کردن نسخه",()=>promoteRelease(env,String(b.version||"")))})}
 if(path==="release/delete"&&req.method==="POST"){const b=await req.json();return json({ok:true,...await withHeavyOperation(env,"release-delete:"+String(b.version||""),"حذف نسخه",()=>deleteRelease(env,String(b.version||"")))})}
 if(path==="release/notify"&&req.method==="POST"){const b=await req.json();return json({ok:true,...await withHeavyOperation(env,"release-notify","اطلاع‌رسانی نسخه",()=>notifyRelease(env,String(b.version||"")))})}
 if(path==="release/github"&&req.method==="POST"){const b=await req.json();return json({ok:true,...await withHeavyOperation(env,"release-github","انتشار GitHub",()=>publishGitHub(env,String(b.version||"")))})}
 if(path==="github/test"&&req.method==="GET"){const c=await getConfig(env);const repo=await ghRequest(env,`/repos/${c.githubRepo||DEFAULT_REPO}`);return json({ok:true,repo:{full_name:repo.full_name,private:repo.private,default_branch:repo.default_branch,push_permissions:repo.permissions?.push??null}})}
 if(path==="direct/verify"&&req.method==="POST"){const b=await req.json(),token=String(b.token||"").trim();await verifyCfToken(token);const accounts=await cfAccounts(token);return json({ok:true,accounts:accounts.map(a=>({id:a.id,name:a.name}))})}
 if(path==="direct/install"&&req.method==="POST"){const b=await req.json();return json({ok:true,...await withHeavyOperation(env,"direct-install","نصب مستقیم",async()=>{const token=String(b.token||"").trim(),accounts=await cfAccounts(token),account=accounts.find(a=>a.id===b.accountId);if(!account)throw new AppError("Cloudflare Account پیدا نشد.",400);let rel=null;if(b.version)rel=await getRelease(env,String(b.version||"").trim().replace(/^v/i,""));else rel=b.channel==="public"?await getPublicRelease(env):await getBetaRelease(env);if(!rel)throw new AppError("نسخه انتخاب‌شده پیدا نشد.",404);const p=await createPanel(env,"admin","admin-test",token,account,rel,{scriptName:b.scriptName});return {panel:{...p,cfToken:undefined,panelPassword:undefined},password:p.password}})})}
 if(path==="direct/action"&&req.method==="POST"){const b=await req.json(),p=await kvJson(env,"panel:"+String(b.panelId||""),null);if(!p)throw new AppError("پنل پیدا نشد.",404);const rel=b.channel==="beta"?await getBetaRelease(env):await getPublicRelease(env);if(b.action==="update"||b.action==="reinstall"){const up=await updatePanel(env,p,rel);const x={...up};delete x.cfToken;delete x.panelPassword;return json({ok:true,panel:x})}if(b.action==="clean"){const np=await cleanReinstallPanel(env,p,rel);const x={...np};delete x.cfToken;delete x.panelPassword;return json({ok:true,panel:x,password:np.password})}if(b.action==="delete")return json({ok:true,...await removePanel(env,p)});throw new AppError("عملیات نامعتبر است.",400)}
 if(path==="panel/action"&&req.method==="POST"){const b=await req.json();return json({ok:true,...await withHeavyOperation(env,"panel-action:"+String(b.panelId||""),"عملیات پنل",async()=>{const p=await kvJson(env,"panel:"+String(b.panelId||""),null);if(!p)throw new AppError("پنل پیدا نشد.",404);let rel=null;if(b.version)rel=await getRelease(env,String(b.version||"").trim().replace(/^v/i,""));else rel=b.channel==="beta"?await getBetaRelease(env):await getPublicRelease(env);if((b.action==="update"||b.action==="reinstall"||b.action==="clean")&&!rel)throw new AppError("نسخه انتخاب‌شده پیدا نشد.",404);if(b.action==="update"||b.action==="reinstall"){const up=await updatePanel(env,p,rel);const x={...up};delete x.cfToken;delete x.panelPassword;return {panel:x}}if(b.action==="clean"){const np=await cleanReinstallPanel(env,p,rel);const x={...np};delete x.cfToken;delete x.panelPassword;return {panel:x,password:np.password}}if(b.action==="delete")return await removePanel(env,p);throw new AppError("عملیات نامعتبر است.",400)})})}
 return json({ok:false,error:"Not found"},404)
 }catch(e){return json({ok:false,error:String(e.message||e)},e.status||500)}}

function setupPage(){return `<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>JavidPanel Installer Setup</title><link rel="icon" href="/favicon.ico"><style>@font-face{font-family:Vazir;src:local(Vazir),local(Vazirmatn);font-display:swap}*{box-sizing:border-box}body{margin:0;background:#07111f;color:#e8f0fa;font-family:Vazir,Tahoma,Arial,sans-serif}.box{max-width:560px;margin:7vh auto;background:#0c1a2d;border:1px solid #1f3652;border-radius:16px;padding:22px}h1{font-size:20px;margin:0 0 6px}.muted{color:#8fa9c8;font-size:12px;line-height:1.8}.field{margin:12px 0}label{display:block;font-size:12px;color:#9db4ce;margin-bottom:5px}input{width:100%;background:#081421;border:1px solid #29445f;color:#fff;border-radius:8px;padding:10px}.btn{width:100%;border:0;border-radius:8px;padding:10px;background:#1976d2;color:white;cursor:pointer}.msg{margin-top:10px;font-size:12px;line-height:1.8}.ok{color:#7fe1b7}.bad{color:#ff9aa5}.code{font-family:monospace;direction:ltr;background:#07131f;padding:8px;border-radius:7px}</style></head><body><div class="box"><h1>راه‌اندازی JavidPanel Installer</h1><div class="muted">فقط بار اول انجام می‌شود. رمز مدیریت با PBKDF2-SHA256 و 100,000 iteration ذخیره می‌شود؛ اگر Bot Token را هم وارد کنی، Webhook همان لحظه تنظیم می‌شود.</div><div id="health" class="msg"></div><form id="f"><div class="field"><label>رمز مدیریت (حداقل ۱۲ کاراکتر)</label><input id="p" type="password" required minlength="12"></div><div class="field"><label>Telegram Bot Token — اختیاری</label><input id="t" type="password" placeholder="123456:ABC..."></div><button class="btn">راه‌اندازی</button></form><div id="m" class="msg"></div></div><script>const m=document.getElementById('m'),h=document.getElementById('health');fetch('/setup/status').then(r=>r.json()).then(d=>{h.innerHTML='MASTER_KEY: <b class="'+(d.masterKey?'ok':'bad')+'">'+(d.masterKey?'آماده':'تنظیم نشده')+'</b>';if(d.configured)location.href='/admin'});document.getElementById('f').onsubmit=async e=>{e.preventDefault();m.textContent='در حال راه‌اندازی…';const r=await fetch('/setup',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({password:document.getElementById('p').value,botToken:document.getElementById('t').value})});const d=await r.json();if(!r.ok){m.className='msg bad';m.textContent=d.error||'خطا';return}m.className='msg ok';m.textContent='انجام شد. در حال انتقال به پنل مدیریت…'+(d.warning?' '+d.warning:'');setTimeout(()=>location.href='/admin',900)};</script></body></html>`}

